-- PREPARED from steward factcheck-2026-11-09 (opt-out steps). Elliot OK 9 Nov 11:53 UK.
-- Updates summary + source_urls for five compliant_with_caveats tools only.
-- Badge/compliance_status unchanged. No schema changes. Fail-closed guards on current rows.
SELECT 'before_snapshot' AS snapshot, domain, compliance_status, summary, source_urls, last_checked_at, manual_override FROM tools WHERE domain IN ('cursor.com','grammarly.com','kimi.com','otter.ai','perplexity.ai') ORDER BY domain;
SELECT CASE WHEN (SELECT COUNT(*) FROM tools WHERE domain='cursor.com' AND compliance_status='compliant_with_caveats' AND summary='If you choose to turn off "Privacy Mode": we may use and store codebase data, prompts, editor actions, code snippets ... to improve our AI features and train our models.')=1 THEN 'ok: cursor.com' ELSE json('GUARD FAILED: cursor.com has changed; review again') END AS guard_target;
SELECT CASE WHEN (SELECT COUNT(*) FROM tools WHERE domain='grammarly.com' AND compliance_status='compliant_with_caveats' AND summary='"Product improvements include (1) training and validating our AI and machine learning models". "Product Improvement and Training is on for individual users by default." Grammarly''s help page explains "How do I turn Product Improvement and Training on or off?"')=1 THEN 'ok: grammarly.com' ELSE json('GUARD FAILED: grammarly.com has changed; review again') END AS guard_target;
SELECT CASE WHEN (SELECT COUNT(*) FROM tools WHERE domain='kimi.com' AND compliance_status='compliant_with_caveats' AND summary='"the platform may use users'' input data, instructions, and generated responses for model training". Opt-out by request: "If you do not want your conversation data to be used for training, you can contact customer support ... and submit a request."')=1 THEN 'ok: kimi.com' ELSE json('GUARD FAILED: kimi.com has changed; review again') END AS guard_target;
SELECT CASE WHEN (SELECT COUNT(*) FROM tools WHERE domain='otter.ai' AND compliance_status='compliant_with_caveats' AND summary='Privacy policy: "training our proprietary AI technology on de-identified audio recordings and on transcriptions (which may contain Personal Information)". Otter''s help centre gives an opt-out: Account Settings > Meetings > Feedback and Training, set Help improve Otter to "Don''t allow sharing", and "Otter will not access your conversation for training and product improvement." The policy doesn''t say whether this also covers de-identified training.')=1 THEN 'ok: otter.ai' ELSE json('GUARD FAILED: otter.ai has changed; review again') END AS guard_target;
SELECT CASE WHEN (SELECT COUNT(*) FROM tools WHERE domain='perplexity.ai' AND compliance_status='compliant_with_caveats' AND summary='For Free, Perplexity Pro and Perplexity Max users, AI Data Retention is enabled by default. However, these users can control whether their data is used for AI model training.')=1 THEN 'ok: perplexity.ai' ELSE json('GUARD FAILED: perplexity.ai has changed; review again') END AS guard_target;
UPDATE tools SET summary='"If you enable Privacy Mode in Cursor''s settings: Customer Data will not be used for training by Cursor. Cursor maintains zero data retention (ZDR) agreements with all providers, and AI model providers will not store or train on your data." "To opt out of training: open Cursor Settings (Mac: Cmd+Shift+J; Windows/Linux: Ctrl+Shift+J), click General in the sidebar, then toggle Privacy Mode on." "If you choose to turn off Privacy Mode: we may use and store codebase data, prompts, editor actions, code snippets, and other code data and actions to improve our AI features and train our models." "Non-ZDR models will be designated as such or require an admin to opt-in to enable the model for your workspace." For teams, Privacy Mode is enabled by default; admins can enforce it organisation-wide. Abuse/risk classifiers may still store flagged prompts per provider policy. Sources: cursor.com/help/security-and-privacy/privacy (fetched 9 November 2026); cursor.com/data-use, last updated 3 September 2026.',
  source_urls='["https://cursor.com/help/security-and-privacy/privacy", "https://cursor.com/data-use"]',
  last_checked_at='2026-11-09T11:53:00.000Z',
  last_check_note=NULL,
  manual_override=1,
  updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now')
WHERE domain='cursor.com' AND compliance_status='compliant_with_caveats';
UPDATE tools SET summary='"Product improvements include (1) training and validating our AI and machine learning models." "Product Improvement and Training is on for individual users by default." "For Grammarly Free and Premium Accounts: go to account.grammarly.com/security/privacy and click the Product Improvement and Training toggle to turn it off." "For Grammarly Pro accounts with one user: go to account.grammarly.com/admin/data_settings and click the Product Improvement and Training toggle to turn it off." "Only admins can change the Product Improvement and Training setting for multi-user accounts at account.grammarly.com/admin/data_settings." "When this control is turned off, none of the content a user inputs into an application or website where our product is active will be used for training or product improvement for other users. We may still collect non-content data, such as writing statistics, and may use that data for product improvement and training." Sales/Enterprise/Education (and Sales-purchased Pro/Business): Product Improvement and Training is off by default. Source: Grammarly help article Product Improvement and Training Control; fetched 9 November 2026.',
  source_urls='["https://support.grammarly.com/hc/en-us/articles/25555503115277-Product-Improvement-and-Training-Control"]',
  last_checked_at='2026-11-09T11:53:00.000Z',
  last_check_note=NULL,
  manual_override=1,
  updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now')
WHERE domain='grammarly.com' AND compliance_status='compliant_with_caveats';
UPDATE tools SET summary='"the platform may use users'' input data, instructions, and generated responses for model training." "If you do not want your conversation data to be used for training, you can contact customer support at support@moonshot.cn and submit a request. We will complete the opt-out registration within 5-7 working days after verifying your identity, and will stop using your content for model training." "Account-level opt-out: Per-conversation or per-file opt-out is not currently supported." "Once registration is complete, neither your historical conversation data nor any newly generated data will be included in the model training dataset." Kimi Business (enterprise) data does not enter the model training pipeline by default. Source: kimi.com/en/help/others/data-usage, updated 5 November 2026; fetched 9 November 2026.',
  source_urls='["https://www.kimi.com/en/help/others/data-usage"]',
  last_checked_at='2026-11-09T11:53:00.000Z',
  last_check_note=NULL,
  manual_override=1,
  updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now')
WHERE domain='kimi.com' AND compliance_status='compliant_with_caveats';
UPDATE tools SET summary='"training our proprietary AI technology on de-identified audio recordings and on transcriptions (which may contain Personal Information)" "Navigate to Account Settings > Meetings. Scroll down to Feedback and Training. Next to Help improve Otter, set your preference in the drop-down to Don''t allow sharing." "If your setting is set to Don''t allow sharing, when submitting feedback, Otter will not access your conversation for training and product improvement." "Access to all past conversations will be removed for training. Future conversations will not be used for training." The Meetings > Feedback and Training control is account-wide. The privacy policy (effective 16 June 2026) still lists de-identified audio/transcript training as a processing purpose and does not name that control, so these steps are Otter''s documented feedback/training opt-out rather than a claim that every training purpose stops. Sources: help.otter.ai Provide feedback to Otter (updated 26 August 2025); otter.ai/privacy-policy; fetched 9 November 2026.',
  source_urls='["https://otter.ai/privacy-policy", "https://help.otter.ai/hc/en-us/articles/25352082563863-Provide-feedback-to-Otter"]',
  last_checked_at='2026-11-09T11:53:00.000Z',
  last_check_note=NULL,
  manual_override=1,
  updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now')
WHERE domain='otter.ai' AND compliance_status='compliant_with_caveats';
UPDATE tools SET summary='"For Free, Perplexity Pro and Perplexity Max users, AI Data Retention is enabled by default. However, these users can control whether their data is used for AI model training." "To opt out of AI training: navigate to Account settings, go to the Preferences page, locate the AI data retention toggle (also called AI Data Usage), and toggle it off." "Opt-outs only apply to data collected after the opt-out date. Previously collected training data cannot be deleted or removed." "Enterprise customers'' data is never used or retained for training AI models." "Data may still be processed for service operation, legal compliance, and product improvement." Sources: perplexity.ai/help-center Data Collection at Perplexity (last modified 31 August 2026) and Account Settings; fetched 9 November 2026.',
  source_urls='["https://www.perplexity.ai/help-center/en/articles/11564572-data-collection-at-perplexity", "https://www.perplexity.ai/help-center/en/articles/10352990-account-settings"]',
  last_checked_at='2026-11-09T11:53:00.000Z',
  last_check_note=NULL,
  manual_override=1,
  updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now')
WHERE domain='perplexity.ai' AND compliance_status='compliant_with_caveats';
SELECT 'after' AS snapshot, domain, compliance_status, manual_override, length(summary) AS summary_len, source_urls, last_checked_at FROM tools WHERE domain IN ('cursor.com','grammarly.com','kimi.com','otter.ai','perplexity.ai') ORDER BY domain;
